

import datetime as dt
import typing

from ..core.client_wrapper import AsyncClientWrapper, SyncClientWrapper
from ..core.request_options import RequestOptions
from ..types.api_key_created import ApiKeyCreated
from ..types.cursor import Cursor
from ..types.uuid_ import Uuid
from .raw_client import AsyncRawApiKeysClient, RawApiKeysClient
from .types.list_api_keys_response import ListApiKeysResponse


OMIT = typing.cast(typing.Any, ...)


class ApiKeysClient:
    def __init__(self, *, client_wrapper: SyncClientWrapper):
        self._raw_client = RawApiKeysClient(client_wrapper=client_wrapper)

    @property
    def with_raw_response(self) -> RawApiKeysClient:
        """
        Retrieves a raw implementation of this client that returns raw responses.

        Returns
        -------
        RawApiKeysClient
        """
        return self._raw_client

    def list_api_keys(
        self,
        *,
        cursor: typing.Optional[Cursor] = None,
        limit: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ListApiKeysResponse:
        """
        Parameters
        ----------
        cursor : typing.Optional[Cursor]

        limit : typing.Optional[int]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ListApiKeysResponse
            The request has succeeded.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.api_keys.list_api_keys()
        """
        _response = self._raw_client.list_api_keys(cursor=cursor, limit=limit, request_options=request_options)
        return _response.data

    def create_api_key(
        self,
        *,
        idempotency_key: Uuid,
        name: str,
        expires_at: typing.Optional[dt.datetime] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ApiKeyCreated:
        """
        Parameters
        ----------
        idempotency_key : Uuid
            Stable UUID generated by the caller for safe request retries.

        name : str

        expires_at : typing.Optional[dt.datetime]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ApiKeyCreated
            The request has succeeded and a new resource has been created as a result.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.api_keys.create_api_key(
            idempotency_key="Idempotency-Key",
            name="name",
        )
        """
        _response = self._raw_client.create_api_key(
            idempotency_key=idempotency_key, name=name, expires_at=expires_at, request_options=request_options
        )
        return _response.data

    def revoke_api_key(self, api_key_id: Uuid, *, request_options: typing.Optional[RequestOptions] = None) -> None:
        """
        Parameters
        ----------
        api_key_id : Uuid

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        None

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.api_keys.revoke_api_key(
            api_key_id="apiKeyId",
        )
        """
        _response = self._raw_client.revoke_api_key(api_key_id, request_options=request_options)
        return _response.data


class AsyncApiKeysClient:
    def __init__(self, *, client_wrapper: AsyncClientWrapper):
        self._raw_client = AsyncRawApiKeysClient(client_wrapper=client_wrapper)

    @property
    def with_raw_response(self) -> AsyncRawApiKeysClient:
        """
        Retrieves a raw implementation of this client that returns raw responses.

        Returns
        -------
        AsyncRawApiKeysClient
        """
        return self._raw_client

    async def list_api_keys(
        self,
        *,
        cursor: typing.Optional[Cursor] = None,
        limit: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ListApiKeysResponse:
        """
        Parameters
        ----------
        cursor : typing.Optional[Cursor]

        limit : typing.Optional[int]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ListApiKeysResponse
            The request has succeeded.

        Examples
        --------
        import asyncio

        from fern import AsyncFernApi

        client = AsyncFernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.api_keys.list_api_keys()


        asyncio.run(main())
        """
        _response = await self._raw_client.list_api_keys(cursor=cursor, limit=limit, request_options=request_options)
        return _response.data

    async def create_api_key(
        self,
        *,
        idempotency_key: Uuid,
        name: str,
        expires_at: typing.Optional[dt.datetime] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ApiKeyCreated:
        """
        Parameters
        ----------
        idempotency_key : Uuid
            Stable UUID generated by the caller for safe request retries.

        name : str

        expires_at : typing.Optional[dt.datetime]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ApiKeyCreated
            The request has succeeded and a new resource has been created as a result.

        Examples
        --------
        import asyncio

        from fern import AsyncFernApi

        client = AsyncFernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.api_keys.create_api_key(
                idempotency_key="Idempotency-Key",
                name="name",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.create_api_key(
            idempotency_key=idempotency_key, name=name, expires_at=expires_at, request_options=request_options
        )
        return _response.data

    async def revoke_api_key(
        self, api_key_id: Uuid, *, request_options: typing.Optional[RequestOptions] = None
    ) -> None:
        """
        Parameters
        ----------
        api_key_id : Uuid

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        None

        Examples
        --------
        import asyncio

        from fern import AsyncFernApi

        client = AsyncFernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.api_keys.revoke_api_key(
                api_key_id="apiKeyId",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.revoke_api_key(api_key_id, request_options=request_options)
        return _response.data
